"""Нейтральная модель спана: ЧТО в спане есть — без знания о том, КАК его пишет вендор.

**Зачем отдельный модуль.** До форма спана была записана литералами в четырёх местах двух
репозиториев, и при этом в ДВУХ разных диалектах одного вендора ( — плоские ключи `ag.session.id`, — вложенный `ag.type.span`). Пока форма живёт по месту вызова, «переключить вендора» нельзя в
принципе: второй приёмник потребовал бы второй такой же россыпи. Здесь остаётся только СМЫСЛ, а
вложенность и имена ключей — дело рендера вендора (`agenta.py`, `openlit.py`).

**Чего здесь НЕТ и почему.** Ни одного вендорского литерала: ни `ag.`, ни `gen_ai.`. Это держит
правило гейта `make arch` («знание о ФОРМЕ СПАНА — только под `core/agent_core/vendors/`»), и оно же
делает модуль читаемым без знания вендора.
"""
from __future__ import annotations

from dataclasses import dataclass

#: Типы, которые различает нейтральная модель. Значения — НАШИ слова; как они ложатся в конкретного
#: вендора, решает адаптер: `agenta.py` кладёт их в `ag.type.span`, `openlit.py` — в `gen_ai.operation.name`.
WORKFLOW = "workflow"
NODE = "node"
AGENT = "agent"


@dataclass(frozen=True)
class SpanShape:
    """Спан в нейтральных словах: тип, имя шага, хеш сессии, ссылки на объекты вендора.

    **`kind=None` — не «забыли заполнить», а отдельный измеренный случай:** спан, который НЕ ОБЪЯВЛЯЕТ
    свой тип (форма; ею живёт спан хода сервиса). Приёмник оставляет такому спану тип по умолчанию
    (`TASK`) — это факт, снятый пробой `e20a`, и он СОХРАНЁН, а не «починен»: смена типа — это смена
    формы трейса, и сюда она не входит.

    **`session_id` приходит УЖЕ хешированным.** Хеш считается вызывающим (`spans.session_id_for`,
    `telemetry.span_attributes`): это НАШЕ правило приватности (в трейс не уходит идентификатор
    человека), а не свойство вендора, и у второго вендора оно обязано быть тем же.
    """

    kind: str | None = None
    #: Имя узла пайплайна/шага. У обоих сайтов оно ложится В ОДИН ключ, поэтому и поле одно — сведение
    #: двух имён (`node_name` и `step`) в одно сделано осознанно: это один смысл, а не два.
    step: str = ""
    session_id: str = ""
    agent_id: str = ""
    workflow_id: str = ""
    workflow_slug: str = ""
    revision_id: str = ""


@dataclass(frozen=True)
class Usage:
    """Расход шага: итог и (когда провайдер его отдал) разбивка на вход и выход.

    **Почему хранится И итог, И разбивка.** Разбивку знает не каждый вызывающий: `run.py` получает её
    из `Reply.usage`, а тестовые двойники задают только `tokens`. Терять итог из-за отсутствия разбивки
    нельзя — иначе починка витрины метрик сделала бы хуже, чем было.
    """

    total: int = 0
    prompt_tokens: int = 0
    completion_tokens: int = 0
    tool_calls: int = 0

    @property
    def has_breakdown(self) -> bool:
        """Отдал ли провайдер разбивку. Ноль-ноль означает «неизвестно», а не «пустой шаг»."""
        return bool(self.prompt_tokens or self.completion_tokens)
